class Solution { private long countAtMost(int[] nums,int limit){int[] frequency=new int[100001];int left=0,distinct=0;long count=0;for(int right=0;right<nums.length;right++){if(frequency[nums[right]]++==0)distinct++;while(distinct>limit){if(--frequency[nums[left++]]==0)distinct--;}count+=right-left+1;}return count;}public int medianOfUniquenessArray(int[] nums){long total=(long)nums.length*(nums.length+1)/2,target=(total+1)/2;int low=1,high=nums.length;while(low<high){int middle=(low+high)/2;if(countAtMost(nums,middle)>=target)high=middle;else low=middle+1;}return low;} }
